create table xxcus.xxfnd_feature_pages (
    app_alias             varchar2(255 byte) not null enable,
    page_id               number not null enable,
    feature_code          varchar2(30 byte) not null enable,
    created_by            varchar2(255 byte) not null enable,
    creation_date         timestamp(6) not null enable,
    last_updated_by       varchar2(255 byte) not null enable,
    last_update_date      timestamp(6) not null enable,
    last_update_login     varchar2(255 byte),
    object_version_number number default 1 not null enable,
    tab_label             varchar2(60 byte),
    tab_sequence          number
);

alter table xxcus.xxfnd_feature_pages
    add constraint xxfnd_feature_pages_pk primary key ( app_alias,
                                                        page_id )
        using index enable;


